-- Phase 1 foundational schema. PostgreSQL UUIDs are generated by Prisma's client.
CREATE TABLE "companies" (
  "id" UUID PRIMARY KEY, "name" TEXT NOT NULL, "legal_name" TEXT,
  "base_currency" CHAR(3) NOT NULL DEFAULT 'PHP', "active" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL
);
CREATE TABLE "branches" (
  "id" UUID PRIMARY KEY, "company_id" UUID NOT NULL REFERENCES "companies"("id") ON DELETE RESTRICT,
  "code" TEXT NOT NULL, "name" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("company_id", "code")
);
CREATE TABLE "departments" (
  "id" UUID PRIMARY KEY, "company_id" UUID NOT NULL REFERENCES "companies"("id") ON DELETE RESTRICT,
  "code" TEXT NOT NULL, "name" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("company_id", "code")
);
CREATE TABLE "users" (
  "id" UUID PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "password_hash" TEXT NOT NULL,
  "display_name" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL
);
CREATE TABLE "user_sessions" (
  "id" UUID PRIMARY KEY, "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
  "token_hash" TEXT NOT NULL UNIQUE, "expires_at" TIMESTAMPTZ NOT NULL,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "user_agent" TEXT
);
CREATE INDEX "user_sessions_user_id_expires_at_idx" ON "user_sessions"("user_id", "expires_at");
CREATE TABLE "user_companies" (
  "user_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,
  "company_id" UUID NOT NULL REFERENCES "companies"("id") ON DELETE RESTRICT,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY("user_id", "company_id")
);
CREATE TABLE "roles" (
  "id" UUID PRIMARY KEY, "code" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL,
  "description" TEXT, "system_role" BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE "permissions" ("id" UUID PRIMARY KEY, "code" TEXT NOT NULL UNIQUE, "description" TEXT NOT NULL);
CREATE TABLE "user_company_roles" (
  "user_id" UUID NOT NULL, "company_id" UUID NOT NULL, "role_id" UUID NOT NULL REFERENCES "roles"("id") ON DELETE RESTRICT,
  PRIMARY KEY("user_id", "company_id", "role_id"),
  FOREIGN KEY("user_id", "company_id") REFERENCES "user_companies"("user_id", "company_id") ON DELETE CASCADE
);
CREATE TABLE "role_permissions" (
  "role_id" UUID NOT NULL REFERENCES "roles"("id") ON DELETE CASCADE,
  "permission_id" UUID NOT NULL REFERENCES "permissions"("id") ON DELETE CASCADE,
  PRIMARY KEY("role_id", "permission_id")
);
CREATE TABLE "fiscal_years" (
  "id" UUID PRIMARY KEY, "company_id" UUID NOT NULL REFERENCES "companies"("id") ON DELETE RESTRICT,
  "name" TEXT NOT NULL, "starts_on" DATE NOT NULL, "ends_on" DATE NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN',
  UNIQUE("company_id", "name"), CHECK("starts_on" <= "ends_on")
);
CREATE TABLE "accounting_periods" (
  "id" UUID PRIMARY KEY, "fiscal_year_id" UUID NOT NULL REFERENCES "fiscal_years"("id") ON DELETE RESTRICT,
  "name" TEXT NOT NULL, "starts_on" DATE NOT NULL, "ends_on" DATE NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN',
  UNIQUE("fiscal_year_id", "name"), CHECK("starts_on" <= "ends_on")
);
CREATE TABLE "accounts" (
  "id" UUID PRIMARY KEY, "company_id" UUID NOT NULL REFERENCES "companies"("id") ON DELETE RESTRICT,
  "parent_id" UUID REFERENCES "accounts"("id") ON DELETE RESTRICT, "code" TEXT NOT NULL, "name" TEXT NOT NULL,
  "account_type" TEXT NOT NULL, "normal_balance" TEXT NOT NULL, "description" TEXT,
  "statement_mapping" TEXT, "cash_flow_class" TEXT, "control_account" BOOLEAN NOT NULL DEFAULT FALSE,
  "posting_restricted" BOOLEAN NOT NULL DEFAULT FALSE, "active" BOOLEAN NOT NULL DEFAULT TRUE,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL,
  UNIQUE("company_id", "code")
);
CREATE INDEX "accounts_company_id_account_type_active_idx" ON "accounts"("company_id", "account_type", "active");
CREATE TABLE "audit_events" (
  "id" UUID PRIMARY KEY, "company_id" UUID REFERENCES "companies"("id") ON DELETE RESTRICT,
  "user_id" UUID REFERENCES "users"("id") ON DELETE SET NULL, "action" TEXT NOT NULL,
  "entity_type" TEXT, "entity_id" TEXT, "metadata" JSONB NOT NULL DEFAULT '{}'::jsonb,
  "ip_address" TEXT, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX "audit_events_company_id_created_at_idx" ON "audit_events"("company_id", "created_at");
CREATE INDEX "audit_events_user_id_created_at_idx" ON "audit_events"("user_id", "created_at");
